return buildCommonSensorMessages(msg);

function buildCommonSensorMessages(msg) {
    const payload = msg.payload;
    const sensors = Array.isArray(payload.sensors) ? payload.sensors : [];
    const lineId = payload.line.line_id;
    const equipmentId = payload.equipment.equipment_id;
    const equipmentType = payload.equipment.equipment_type;
    const instanceId = payload.equipment.instance_id;
    const base = {
        timestamp: payload.timestamp,
        line_id: lineId,
        equipment_id: equipmentId,
        equipment_type: equipmentType,
        instance_id: instanceId,
        operation: payload.operation,
        sample: payload.sample
    };
    const prefix = `das/common/${lineId}/${equipmentId}`;
    const byId = Object.fromEntries(sensors.map(sensor => [sensor.sensor_id, sensor]));
    const messages = [];
    if (byId['VIB-01']) {
        messages.push({ topic: `${prefix}/vibration/window`, payload: { ...base, sensor_id: 'VIB-01', window: byId['VIB-01'].window, values: byId['VIB-01'].values, unit: byId['VIB-01'].unit } });
    }
    if (byId['CUR-01']) {
        messages.push({ topic: `${prefix}/current`, payload: { ...base, sensor_id: 'CUR-01', sample: byId['CUR-01'].sample, value: byId['CUR-01'].values.current, unit: byId['CUR-01'].unit } });
    }
    if (byId['VOLT-01']) {
        messages.push({ topic: `${prefix}/voltage`, payload: { ...base, sensor_id: 'VOLT-01', sample: byId['VOLT-01'].sample, values: byId['VOLT-01'].values, unit: byId['VOLT-01'].unit } });
    }
    if (byId['TEMP-01']) {
        messages.push({ topic: `${prefix}/temperature`, payload: { ...base, sensor_id: 'TEMP-01', sample: byId['TEMP-01'].sample, value: byId['TEMP-01'].values.equipment_temperature, unit: byId['TEMP-01'].unit } });
    }
    return [messages];
}

msg.payload = summarize(msg.payload);
