function summarize(payload) {
    const summary = {
        topic: msg.topic,
        line_id: payload.line_id,
        equipment_id: payload.equipment_id,
        equipment_type: payload.equipment_type,
        instance_id: payload.instance_id,
        sensor_id: payload.sensor_id
    };
    if (payload.sensor_id === 'VIB-01') {
        const values = payload.values || {};
        const window = payload.window || {};
        summary.vibration_rms = values.vibration_rms;
        summary.sample_rate_hz = window.sample_rate_hz;
        summary.window_size = window.window_size || window.sample_count;
        summary.stride = window.stride;
        summary.raw_length = Array.isArray(values.vibration_raw) ? values.vibration_raw.length : 0;
        summary.model_input_key = window.model_input ? window.model_input.input_key : undefined;
    } else {
        summary.value = payload.value;
        summary.values = payload.values;
        summary.unit = payload.unit;
    }
    return summary;
}

